import {executionUI} from '/execution.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialRoute=new URLSearchParams(location.hash.slice(1));
let screen=initialRoute.get('screen')||'project',legacyRuns=[];
let token='',projects=[],active=initialRoute.get('screen')==='new'?null:(initialRoute.get('id')||localStorage.getItem('research-project')),tab=initialRoute.get('view')||'compare',selected=new Set(),provider=localStorage.getItem('relay-provider'),model=localStorage.getItem('relay-model'),signature='',dirty=false,editorFile='tex',zoom=1,expandedTopics=new Set(),pairFilter='all',pairQuery='',comparisonCache={key:'',data:null};
const example='Do graph neural networks improve traffic forecasting over transformer models under comparable datasets and forecast horizons?';
const baselineExample={q:'Before I adopt published METR-LA and PEMS04 results as baselines, which reported comparisons between GTS, Graph WaveNet, MTGNN, AGCRN, and STAEformer hold under matched protocols?',seeds:'2101.06861\n1906.00121\n2005.11650\n2007.02842\n2308.10425'};
const BUSY=['discovering','drafting','investigating'];
const current=()=>projects.find(p=>p.id===active), busy=p=>BUSY.includes(p.status);
const FIELD_LABELS={method:'Model',dataset:'Dataset',datasetVersion:'Dataset version',split:'Train/val/test split',horizon:'Forecast horizon',aggregation:'Aggregation',preprocessing:'Preprocessing',metricDefinition:'Metric definition',provenance:'Provenance',citedFrom:'Cited from',locator:'Source location',name:'Metric',value:'Value',unit:'Unit',direction:'Direction'};
const CONTEXT=['method','dataset','datasetVersion','split','horizon','aggregation','preprocessing','metricDefinition','provenance','citedFrom','locator'];
const SUPPORT={quoted:['Quoted','In the result quote or a field quote'],nearby:['Near result','Found near the result in the source'],document:['In paper','Found elsewhere in the paper'],derived:['Derived','Derived from the table column'],repository:['Code','From the authors’ repository, accepted by you'],researcher:['You','Your correction'],default:['Default','Paper’s own method'],missing:['Not stated','The source does not state this'],unsupported:['Rejected','The model claimed a value that is not in the source']};
const OUTCOME={comparable:['Comparable','The context matches'],incompatible:['Incompatible','The settings differ'],insufficient:['Insufficient evidence','Context is not stated']};
const known=v=>!['','unknown','not reported','not stated','n/a','none','null'].includes(String(v??'').trim().toLowerCase());
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','Authorization':'Bearer '+token}:{},body:data?JSON.stringify(data):undefined});const x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');return x;}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').hidden=true,6000)}
function modal(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
$('.close').onclick=()=>$('#dialog').close();
async function refresh(force=false){try{const s=await api('research');projects=s.projects;const sig=JSON.stringify(projects);sidebar();if((force||sig!==signature)&&!dirty){signature=sig;const y=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo(0,y))}}catch(e){toast(e.message)}}
async function beforeNavigate(){if(!dirty)return true;try{await saveEditor();return true}catch(e){toast(e.message);return false}}
function routeTo(node){const q=new URLSearchParams();if(screen==='history')q.set('screen','history');else if(active){q.set('id',active);q.set('view',tab);if(node)q.set('node',node)}else q.set('screen','new');window.history.pushState({},'',location.pathname+'#'+q.toString())}
async function openProject(id,view='compare',node){if(!await beforeNavigate())return;active=id;screen='project';tab=view;localStorage.setItem('research-project',id);selected.clear();if(node)executions.setNode(node);routeTo(node);render();sidebar()}
async function openTab(view){if(!await beforeNavigate())return;tab=view;routeTo();render()}
async function showHistory(){if(!await beforeNavigate())return;try{legacyRuns=(await api('state')).runs}catch(e){toast(e.message)}screen='history';routeTo();render();sidebar()}
function sidebar(){$('#projects').innerHTML=projects.map(p=>`<button class="project-link ${p.id===active&&screen==='project'?'active':''}" data-project="${p.id}">${p.parentProject?'⑂ ':''}${esc((p.branchName||p.hypothesis).slice(0,90))}<small>${p.papers.length} papers · ${esc(p.status)} · ${(p.proposals||[]).filter(x=>x.status==='pending').length} proposals</small></button>`).join('');document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.project));$('#model-button').textContent=(model||'Choose model')+' ⌄';$('#executions').classList.toggle('active',screen==='history')}
$('#executions').onclick=showHistory;
const closeNavigation=()=>{document.body.classList.remove('nav-open');$('#nav-toggle').setAttribute('aria-expanded','false')};
$('#nav-toggle').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('#nav-toggle').setAttribute('aria-expanded',String(open))};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigation()});
document.querySelector('main').addEventListener('click',e=>{if(!e.target.closest('#nav-toggle'))closeNavigation()});
$('#new').onclick=async()=>{if(!await beforeNavigate())return;active=null;screen='project';tab='compare';localStorage.removeItem('research-project');routeTo();render();sidebar()};
window.addEventListener('popstate',async()=>{if(!await beforeNavigate())return;const r=new URLSearchParams(location.hash.slice(1));screen=r.get('screen')==='history'?'history':'project';active=r.get('id');tab=r.get('view')||'compare';if(r.get('node'))executions.setNode(r.get('node'));render();sidebar()});

const TABS=[['map','Question & papers'],['papers','Evidence'],['compare','Comparisons'],['corrections','Corrections'],['write','Experiment & manuscript'],['execution','Execution record']];
function render(){closeNavigation();if(screen==='history'){$('#crumb').textContent='Executions & branches';executions.history();return}const p=current();$('#crumb').textContent=p?'Investigation':'New investigation';if(!p){home();return}
  const pending=(p.proposals||[]).filter(x=>x.status==='pending').length,stale=(p.corrections||[]).filter(c=>c.status==='stale').length;
  const counts={compare:pending?`<span class="tab-count">${pending}</span>`:'',corrections:stale?`<span class="tab-count warn">${stale}</span>`:''};
  $('#main').innerHTML=`<div class="project-head"><div class="kicker">INVESTIGATION / ${esc(p.created.slice(0,10))}${p.branchName?' / ⑂ '+esc(p.branchName):''}</div><h2>${esc(p.hypothesis)}</h2><div class="meta"><span class="badge ${busy(p)?'orange':''}">${busy(p)?'<i class="progress-dot"></i>':''}${esc(p.status==='review'?'Ready for your review':p.status)}</span><span>${p.papers.length} papers</span><span>${p.papers.reduce((n,x)=>n+x.metrics.length,0)} results</span><span>${esc(p.model)} · ${p.tokens.toLocaleString()} tokens</span></div>${busy(p)?`<div class="live-step"><i class="progress-dot"></i>${esc(p.activeStep||'Working…')}</div>`:''}<nav class="tabs journey" aria-label="Investigation steps">${TABS.map(([id,label],i)=>`<button data-tab="${id}" aria-current="${tab===id?'page':'false'}" class="${tab===id?'active':''}"><span class="tab-index">${i+1}</span>${label}${counts[id]||''}</button>`).join('')}</nav></div><div class="workspace">${p.error?`<div class="notice error">${esc(p.error)}</div>`:''}<div id="view"></div></div>`;
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openTab(b.dataset.tab));
  ({execution:executionView,map:mapView,papers:papersView,compare:compareView,corrections:correctionsView,write:writeView}[tab]||compareView)(p)}

function home(){$('#main').innerHTML=`<div class="landing"><div class="hero-intro"><div class="kicker"><span class="signal"></span> CHECK THE COMPARISON BEFORE YOU BUILD ON IT</div><h1>Does that benchmark<br><em>comparison hold?</em></h1><p>Relay investigates published results, exposes missing experimental context,<br>and helps you design the next defensible experiment.</p></div><div class="launch-grid"><div class="launch-main"><form class="hypothesis-box" id="search"><div class="question-heading"><span class="step-label">01 / THE QUESTION</span><span class="private-label">Saved locally</span></div><label for="hypothesis">What comparison do you need to trust?</label><textarea id="hypothesis" required minlength="10" maxlength="2000" placeholder="Which published results can I compare my new method against?"></textarea><label for="seeds" class="seed-label">Papers you are considering as baselines <small>(optional arXiv IDs or links, one per line)</small></label><textarea id="seeds" class="seed-box" placeholder="2101.06861&#10;1906.00121"></textarea><label class="inline-check"><input type="checkbox" id="seed-only"> Only analyze these papers (skip literature search)</label><div class="search-bottom"><span>Public papers and author code · source-checked evidence<br>Your question and retrieved text go to the model you choose.</span><button class="accent" id="discover">Start investigation <span aria-hidden="true">↗</span></button></div></form><div class="example-row"><button class="example" id="baseline-example"><span>BASELINE CHECK</span> GTS, Graph WaveNet, MTGNN, AGCRN, STAEformer <span aria-hidden="true">↗</span></button><button class="example" id="example"><span>OPEN QUESTION</span> Graph networks vs. transformers <span aria-hidden="true">↗</span></button></div><div class="home-history"><span>Pick up where you left off.</span><button id="home-history">Browse executions & branches →</button></div></div><div class="feature-grid" aria-label="Research workflow"><div class="feature"><span class="feature-icon" aria-hidden="true">⌘</span><div><span class="number">01 / EVIDENCE</span><h3>Every number keeps its context.</h3><p>Dataset, split, horizon, aggregation, metric definition, and whether the number was cited or re-run.</p></div></div><div class="feature"><span class="feature-icon" aria-hidden="true">⇄</span><div><span class="number">02 / COMPARE</span><h3>Comparable, incompatible, or unknown.</h3><p>Missing context is never treated as proof of a mismatch. The agent goes looking for it.</p></div></div><div class="feature"><span class="feature-icon" aria-hidden="true">↻</span><div><span class="number">03 / CORRECT</span><h3>Corrections propagate.</h3><p>See which comparisons and manuscript claims change, regenerate them after review, and keep the old state as a branch.</p></div></div></div></div></div>`;
  $('#home-history').onclick=showHistory;$('#example').onclick=()=>{$('#hypothesis').value=example;$('#seeds').value='';$('#seed-only').checked=false;$('#hypothesis').focus()};$('#baseline-example').onclick=()=>{$('#hypothesis').value=baselineExample.q;$('#seeds').value=baselineExample.seeds;$('#seed-only').checked=true;$('#hypothesis').focus()};
  $('#search').onsubmit=async e=>{e.preventDefault();const b=$('#discover');b.disabled=true;b.textContent='Starting…';try{const seeds=$('#seeds').value.split(/[\s,]+/).filter(Boolean);const r=await api('research/start',{hypothesis:$('#hypothesis').value,provider,model,seeds,seedOnly:$('#seed-only').checked});active=r.id;selected.clear();tab='compare';screen='project';localStorage.setItem('research-project',active);routeTo();await refresh(true)}catch(e){toast(e.message);b.disabled=false;b.textContent='Start investigation ↗'}}}

function events(p){return `<div class="activity">${p.events.slice(-7).map(e=>`<div>${esc(e.message)}</div>`).join('')||'Agent preparing…'}</div>`}
function tray(p){return `<div class="compare-tray" id="tray"><div class="tray-label">＋ Focus comparisons<small>Drag papers here to limit comparisons to them</small></div>${p.papers.filter(x=>selected.has(x.id)).map(x=>`<div class="chip"><span>${esc(x.title)}</span><button data-remove="${x.id}" aria-label="Remove ${esc(x.title)}">×</button></div>`).join('')}<button class="primary" id="compare-now">${selected.size>=2?`Compare ${selected.size} papers →`:'Compare all papers →'}</button></div>`}
function bindTray(p){const t=$('#tray');t.ondragover=e=>{e.preventDefault();t.classList.add('over')};t.ondragleave=()=>t.classList.remove('over');t.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(p.papers.some(x=>x.id===id))selected.add(id);mapView(p)};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected.delete(b.dataset.remove);mapView(p)});$('#compare-now').onclick=()=>openTab('compare')}
function mapView(p){const groups={};for(const paper of p.papers)(groups[paper.topic||'Awaiting assessment']??=[]).push(paper);let y=45,nodes='',edges='',centers=[];const edge=(x1,y1,x2,y2)=>`<path d="M${x1},${y1} C${(x1+x2)/2},${y1} ${(x1+x2)/2},${y2} ${x2},${y2}"/>`;
for(const [topic,allPapers] of Object.entries(groups)){const papers=expandedTopics.has(topic)?allPapers:allPapers.slice(0,1);const start=y;for(const paper of papers){const shown=paper.metrics.slice(0,4),metricH=Math.max(145,shown.length*95);nodes+=`<button class="node paper" data-paper="${paper.id}" style="left:505px;top:${y}px"><small>${paper.year||'—'} · ${esc(paper.venue?.slice(0,30)||'Scholarly paper')} ${paper.reviewed?'· ✓':''}</small><strong>${esc(paper.title)}</strong><div class="node-foot"><span>${paper.metrics.length} results · ${esc(paper.sourceRef?'Full text':'Abstract')}</span><span>${paper.relevance??'…'}/100 fit</span></div></button>`;shown.forEach((m,i)=>{nodes+=`<button class="node metric" data-metric-paper="${paper.id}" style="left:810px;top:${y+i*95}px"><small>${esc(m.dataset)} · ${esc(m.horizon)}</small><strong>${esc(m.method)} · ${esc(m.name)} ${esc(m.value)} ${m.verified?'✓':''}</strong></button>`;edges+=edge(759,y+60,810,y+i*95+35)});y+=metricH+20}const cy=start+65;centers.push(cy);nodes+=`<button class="node topic" data-topic="${esc(topic)}" style="left:275px;top:${cy-40}px"><small>${allPapers.length} PAPERS · ${expandedTopics.has(topic)?'COLLAPSE −':'EXPAND +'}</small><strong>${esc(topic)}</strong></button>`;let py=start;for(const paper of papers){edges+=edge(455,cy,505,py+60);py+=Math.max(145,paper.metrics.slice(0,4).length*95)+20}y+=35}
const rootY=160;nodes+=`<div class="node root" style="left:30px;top:${rootY-70}px"><small>YOUR QUESTION</small><strong>${esc(p.hypothesis)}</strong></div>`;for(const cy of centers)edges+=edge(230,rootY,275,cy);
$('#view').innerHTML=`<div class="toolbar"><small>Expand a topic · double-click a paper for its evidence · drag papers into the tray to focus comparisons</small><div><button id="add-paper">＋ Add arXiv paper</button> <button id="zoom-out" aria-label="Zoom out">−</button> <button id="zoom-reset">${Math.round(zoom*100)}%</button> <button id="zoom-in" aria-label="Zoom in">＋</button></div></div><div class="map-layout"><div><div class="map-shell"><div class="map-scroll"><div class="map-canvas" style="width:${1040*zoom}px;height:${Math.max(y,500)*zoom}px"><div id="map-inner" style="width:1040px;height:${Math.max(y,500)}px;transform:scale(${zoom});transform-origin:0 0"><svg width="1040" height="${Math.max(y,500)}">${edges}</svg>${nodes}</div></div></div><div class="map-legend"><span>● Question &nbsp; ◌ Method family &nbsp; □ Paper &nbsp; ◇ Result</span><span>Fit = model relevance estimate</span></div></div>${tray(p)}</div><aside class="map-side"><div class="side-card"><h3>${busy(p)?'<i class="progress-dot"></i>':''} Research agent</h3>${events(p)}</div><div class="side-card"><h3>Where to go next ↗</h3>${p.suggestions.length?p.suggestions.map((s,i)=>`<div class="suggestion"><strong>${esc(s.topic)}</strong><p>Suggested question, not a verified gap in the literature.</p><small>Linked evidence: ${esc((s.paperIds||[]).join(', '))}</small><br><button data-explore="${i}">Explore question ↗</button></div>`).join(''):'<p>Related questions appear after the agent assesses the papers.</p>'}</div></aside></div>${p.synthesis?`<div class="side-card"><h3>Working assessment <span class="badge">${p.synthesisStale?'Earlier assessment · evidence changed':'Unreviewed model interpretation'}</span></h3><p>${esc(p.synthesis)}</p></div>`:''}`;
document.querySelectorAll('[data-paper]').forEach(b=>{b.ondblclick=()=>paperDetail(b.dataset.paper);b.onclick=()=>toast('Double-click to inspect this paper; drag it into the tray.');b.onkeydown=e=>{if(e.key==='Enter')paperDetail(b.dataset.paper)};b.onpointerdown=e=>{if(e.button!==0)return;const start={x:e.clientX,y:e.clientY};let moved=false;b.setPointerCapture(e.pointerId);b.onpointermove=ev=>{if(Math.hypot(ev.clientX-start.x,ev.clientY-start.y)>8){moved=true;b.classList.add('dragging');const r=$('#tray').getBoundingClientRect();$('#tray').classList.toggle('over',ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom)}};b.onpointerup=ev=>{b.onpointermove=null;b.classList.remove('dragging');const r=$('#tray').getBoundingClientRect();$('#tray').classList.remove('over');if(moved&&ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom){selected.add(b.dataset.paper);mapView(p);toast('Paper added to the comparison focus.')}}}});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{expandedTopics.has(b.dataset.topic)?expandedTopics.delete(b.dataset.topic):expandedTopics.add(b.dataset.topic);mapView(p)});document.querySelectorAll('[data-metric-paper]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.metricPaper));bindTray(p);$('#zoom-out').onclick=()=>{zoom=Math.max(.45,zoom-.15);mapView(p)};$('#zoom-in').onclick=()=>{zoom=Math.min(1.6,zoom+.15);mapView(p)};$('#zoom-reset').onclick=()=>{zoom=1;mapView(p)};$('#add-paper').onclick=()=>addPaperDialog(p);document.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>{const q=p.suggestions[+b.dataset.explore].topic;active=null;home();$('#hypothesis').value=q})}
function addPaperDialog(p){modal(`<div class="kicker">ADD A PAPER</div><h2>Add a paper you are considering.</h2><p>Relay retrieves its arXiv full text, extracts results with their context, and adds them to the comparisons.</p><label>arXiv ID or link<input type="text" id="arxiv-id" placeholder="2101.06861"></label><button class="primary" id="add-go" ${busy(p)?'disabled':''}>Add and extract</button>`);$('#add-go').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'add-paper',arxiv:$('#arxiv-id').value});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}}}

function missingCount(x){return x.metrics.reduce((n,m)=>n+(m.missing||[]).length,0)}
function papersView(p){$('#view').innerHTML=`<div class="toolbar"><small>Each result keeps its experimental context. Missing fields are shown, not guessed.</small><span><button id="add-paper">＋ Add arXiv paper</button> <span class="badge">${p.papers.length} real records</span></span></div><div class="paper-list">${p.papers.map(x=>{const cellOk=x.metrics.filter(m=>m.checks?.cell?.ok).length;return `<article class="paper-card"><span class="score">${x.relevance??'…'}/100 fit</span><span class="badge">${x.year||'—'} ${x.reviewed?'· Reviewed':''} ${x.origin==='researcher'?'· Your paper':''}</span><h3>${esc(x.title)}</h3><p>${esc(x.rationale||'Assessment in progress…')}</p><div class="evidence-stats"><span><b>${x.metrics.length}</b> results</span><span><b>${cellOk}</b> table cells matched</span><span class="${missingCount(x)?'warn':''}"><b>${missingCount(x)}</b> context gaps</span><span><b>${x.metrics.filter(m=>m.verified).length}</b> verified</span></div><p class="source-kind">${esc(x.evidenceKind)}</p><button data-inspect="${x.id}">Inspect evidence ↗</button> <button data-add="${x.id}">${selected.has(x.id)?'✓ In focus':'+ Focus'}</button></article>`}).join('')}</div>`;document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.inspect));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{selected.add(b.dataset.add);b.textContent='✓ In focus'});$('#add-paper').onclick=()=>addPaperDialog(p)}

function supportChip(status){const s=SUPPORT[status]||[status||'—',''];return `<span class="support support-${esc(status||'none')}" title="${esc(s[1])}">${esc(s[0])}</span>`}
function evidenceCard(p,x,m,i){const cell=m.checks?.cell,support=m.checks?.support||{};const rejected=Object.entries(m.rejected||{});return `<div class="metric-entry evidence-card"><div class="evidence-head"><h3>${esc(m.method)} · ${esc(m.name)} = ${esc(m.value)} ${known(m.unit)?esc(m.unit):''}</h3><span class="badge">${esc(m.provenance==='own'?'Own experiment':m.provenance==='cited'?'Cited from another paper':m.provenance==='reproduced'?'Baseline re-run by authors':'Provenance unknown')}</span></div>${cell?`<div class="cell-check ${cell.ok?'ok':'warn'}">${cell.ok?'✓':'!'} Table cell: <b>${esc(cell.path)}</b>${cell.caption?` <span>· ${esc(cell.caption.slice(0,110))}</span>`:''}${cell.ok?'':' — the row/column labels do not name this model and metric; check the table.'}</div>`:'<div class="cell-check">Not located in a table. Check the quoted sentence.</div>'}<dl class="metric-grid context-grid">${['name','value','unit','direction',...CONTEXT].map(k=>{const ev=m.evidence?.[k];return `<div class="${(m.missing||[]).includes(k)?'gap':''}"><dt><label for="metric-${i}-${k}">${FIELD_LABELS[k]}</label>${support[k]?supportChip(support[k]):''}</dt><dd><input type="text" id="metric-${i}-${k}" data-edit-metric="${i}" data-field="${k}" value="${esc(m[k])}">${ev?.quote?`<details><summary>${esc(ev.origin==='repository'?'Code evidence':ev.origin==='researcher'?'Your note':'Source quote')}</summary><q>${esc(ev.quote)}</q>${ev.location?`<small>${esc(ev.location)}</small>`:''}</details>`:''}</dd></div>`}).join('')}</dl><blockquote>${esc(m.quote)}${m.quoteLocated?'<small> · row located by Relay from the table cell</small>':''}</blockquote>${rejected.length?`<div class="rejected"><b>Model claims removed by source checks:</b> ${rejected.map(([k,v])=>`${esc(FIELD_LABELS[k]||k)} “${esc(String(v.value).slice(0,80))}” (${esc(v.reason)})`).join('; ')}</div>`:''}${(m.history||[]).length?`<details class="history"><summary>${m.history.length} correction${m.history.length>1?'s':''}</summary>${m.history.map(h=>`<div>${esc(FIELD_LABELS[h.field]||h.field)}: “${esc(h.before)}” → “${esc(h.after)}” <small>${esc(h.origin)} · ${esc(h.at.slice(0,16).replace('T',' '))}</small></div>`).join('')}</details>`:''}<div class="actions"><label><input type="checkbox" class="verify" value="${i}" ${m.verified?'checked':''}> I checked this value and its context against the source.</label>${(m.missing||[]).length?`<button data-investigate-metric="${m.id}" ${busy(p)?'disabled':''}>Investigate ${m.missing.length} gap${m.missing.length>1?'s':''} with agent</button>`:''}</div></div>`}
function paperDetail(id){const p=current(),x=p.papers.find(x=>x.id===id);if(!x)return;modal(`<div class="kicker">PAPER / EXPERIMENTAL EVIDENCE</div><h2>${esc(x.title)}</h2><p>${esc(x.authors.join(', '))} · ${x.year||'—'}<br>${esc(x.venue)} · ${x.citations} citations</p><a href="${esc(x.url)}" target="_blank" rel="noopener">Open original paper ↗</a> &nbsp; <a href="${esc(x.evidenceUrl)}" target="_blank" rel="noopener">Evidence source ↗</a><div class="notice">${esc(x.evidenceKind)}. Relevance ${x.relevance??'—'}/100 is a model estimate of fit, not scientific quality.${x.rejectedMetrics?` ${x.rejectedMetrics} extracted number(s) were discarded because their quote or value was not in the source.`:''}</div><label>Topic family<input type="text" id="paper-topic" value="${esc(x.topic||'Other approaches')}"></label><label>Hypothesis-fit assessment (editable model interpretation)<textarea id="paper-rationale">${esc(x.rationale)}</textarea></label><details><summary>Read abstract</summary><p>${esc(x.abstract||'No abstract returned by the index.')}</p></details><h3>Reported results</h3><p class="hint">Edit a context field to correct it. Relay shows which comparisons and manuscript claims your correction affects. Values must stay inside their quotes.</p><button id="reanalyze" ${busy(p)?'disabled':''}>Re-extract from source</button><label>Evidence limitations (check against the source)<textarea id="paper-limitations">${esc(x.limitations||'Assessment pending.')}</textarea></label>${x.metrics.map((m,i)=>evidenceCard(p,x,m,i)).join('')||'<div class="notice">No verifiable numeric results were extracted. Add a table excerpt below to enrich this paper’s evidence.</div>'}<label>Review notes / reasons for a correction<textarea id="review-note" placeholder="For example: Appendix D says Table 1 used a non-standard metric.">${esc(x.reviewNote||'')}</textarea></label><label><input id="review-paper" type="checkbox" ${x.reviewed?'checked':''}> Include this reviewed paper in manuscript drafting</label><div class="actions"><button class="primary" id="save-review" ${busy(p)?'disabled':''}>Save review and apply corrections</button><button id="add-detail">＋ Focus comparisons</button></div><details class="check-number" ${x.sourceRef?'open':''}><summary>Check a specific number from this paper</summary><p>Point Relay at any value you plan to compare against, for example a table cell. It locates the cell, reads the setup and appendices, and adds the number with its context.</p><div class="check-row"><input type="text" id="check-value" placeholder="2.99" aria-label="Number as printed"><input type="text" id="check-method" placeholder="Model (optional)" aria-label="Model name"><button id="check-go" ${busy(p)?'disabled':''}>Check this number</button></div></details><details><summary>Enrich evidence from a paper or results table</summary><p>Paste a source excerpt including table headers, captions, and evaluation settings. It stays labeled as user-supplied evidence.</p><textarea id="excerpt" placeholder="Paste the experimental section or table here…"></textarea><button id="extract" ${busy(p)?'disabled':''}>Extract results with ${esc(p.model)}</button></details>`);
  $('#save-review').onclick=async()=>{try{const r=await api('research/update',{id:p.id,revision:p.revision,action:'review',paper:id,reviewed:$('#review-paper').checked,verified:[...document.querySelectorAll('.verify:checked')].map(n=>+n.value),note:$('#review-note').value,topic:$('#paper-topic').value,rationale:$('#paper-rationale').value,limitations:$('#paper-limitations').value,metrics:x.metrics.map((m,i)=>Object.fromEntries([...document.querySelectorAll(`[data-edit-metric="${i}"]`)].map(n=>[n.dataset.field,n.value])))});$('#dialog').close();await refresh(true);if(r.corrections?.length){tab='corrections';routeTo();render();toast('Correction applied. Review its impact on comparisons and claims.')}else toast('Evidence review saved.')}catch(e){toast(e.message)}};
  $('#reanalyze').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'analyze',paper:id});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}};$('#add-detail').onclick=()=>{selected.add(id);toast('Added to the comparison focus.')};$('#extract').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'evidence',paper:id,excerpt:$('#excerpt').value});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}};
  document.querySelectorAll('[data-investigate-metric]').forEach(b=>b.onclick=()=>investigate(p,[{paper:id,metric:b.dataset.investigateMetric}]));
  $('#check-go').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'check',paper:id,value:$('#check-value').value.trim(),method:$('#check-method').value.trim()});$('#dialog').close();toast('Checking that number against the paper.');await refresh(true)}catch(e){toast(e.message)}}}

async function investigate(p,targets,pair){try{await api('research/investigate',{id:p.id,revision:p.revision,targets,pair,repository:true});if($('#dialog').open)$('#dialog').close();toast('The agent is investigating. Proposed corrections will need your review.');await refresh(true)}catch(e){toast(e.message)}}
function proposalsPanel(p){const pending=(p.proposals||[]).filter(x=>x.status==='pending');if(!pending.length)return '';return `<section class="proposals"><div class="section-title"><h3>Proposed corrections awaiting your review <span class="badge">${pending.length}</span></h3><p>The agent found these in the sources. Nothing changes until you accept.</p></div>${pending.map(x=>`<article class="proposal"><div class="proposal-head"><span class="badge">${esc(x.origin==='repository'?'From authors’ code':'From the paper')}</span><strong>${esc(FIELD_LABELS[x.field]||x.field)} for ${esc(x.method)} ${esc(x.result)}</strong><small>${esc(x.paperTitle.slice(0,80))}</small></div><div class="proposal-change"><span class="before">${esc(x.current)}</span><span aria-hidden="true">→</span><input type="text" value="${esc(x.value)}" data-proposal-value="${x.id}" aria-label="Proposed value"></div><blockquote>${esc(x.quote)}</blockquote><p>${esc(x.explanation)}</p><small>${esc(x.location)} ${x.url?`· <a href="${esc(x.url)}" target="_blank" rel="noopener">open source ↗</a>`:''}</small><div class="actions"><button class="primary" data-accept="${x.id}" ${busy(p)?'disabled':''}>Accept and propagate</button><button data-reject="${x.id}" ${busy(p)?'disabled':''}>Reject</button></div></article>`).join('')}</section>`}
function bindProposals(p){document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{try{const r=await api('research/update',{id:p.id,revision:p.revision,action:'proposal',proposal:b.dataset.accept,decision:'accept',value:document.querySelector(`[data-proposal-value="${b.dataset.accept}"]`).value});await refresh(true);if(r.correction){tab='corrections';routeTo();render();toast('Correction applied. Here is what it changed.')}}catch(e){toast(e.message)}});document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'proposal',proposal:b.dataset.reject,decision:'reject'});await refresh(true);toast('Proposal rejected. The evidence is unchanged.')}catch(e){toast(e.message)}})}

function pairStatus(pair,field){const c=pair.checks.find(c=>c.field===field);return c?c.status:''}
function pairCard(p,pair){const [label]=OUTCOME[pair.outcome];const fields=[['method','Model'],['value','Reported value'],['dataset','Dataset'],['split','Split'],['horizon','Horizon'],['aggregation','Aggregation'],['metricDefinition','Metric definition'],['provenance','Provenance'],['locator','Source']];const statusFor=f=>f==='aggregation'?pairStatus(pair,'horizon'):f==='value'?'':pairStatus(pair,f);
  const fav=pair.favours?pair[pair.favours]:null;const gaps=[...new Set(pair.checks.filter(c=>['missing','conflict','caveat'].includes(c.status)).map(c=>c.field==='name'?null:c.field).filter(Boolean))];
  return `<article class="pair-card outcome-${pair.outcome}" id="pair-${pair.id}"><header><span class="outcome-badge">${label}</span><strong>${esc(pair.a.method)} ${esc(pair.a.name)} ${esc(pair.a.value)} <span class="vs">vs</span> ${esc(pair.b.method)} ${esc(pair.b.value)}</strong><span class="pair-meta">${esc(pair.a.dataset)}${pair.verified?' · verified':' · not yet verified'}</span></header><div class="pair-grid" role="table"><div class="pg-row pg-head" role="row"><span role="columnheader">Context</span><span role="columnheader">${esc(pair.a.title.slice(0,70))}</span><span role="columnheader">${esc(pair.b.title.slice(0,70))}</span></div>${fields.map(([f,l])=>`<div class="pg-row st-${statusFor(f)}" role="row"><span role="rowheader">${l}</span><span role="cell">${esc(pair.a[f])}</span><span role="cell">${esc(pair.b[f])}</span></div>`).join('')}</div><ul class="pair-why">${pair.explanation.map(e=>`<li>${esc(e)}</li>`).join('')}${pair.caveats.map(c=>`<li class="caveat">Caveat: ${esc(c)}</li>`).join('')}${pair.independent?'':`<li class="caveat">${esc(pair.independence)}</li>`}</ul>${fav?`<p class="favours">${pair.verified?'Within this matched context, the':'Provisionally, the'} lower-error result is <b>${esc(fav.method)}</b> by ${esc(pair.delta)} (${esc(pair.relative)}%). This is a reported difference, not a significance test.</p>`:''}<div class="pair-actions">${gaps.length?`<button class="primary" data-investigate-pair="${pair.id}" ${busy(p)?'disabled':''}>Investigate ${gaps.map(g=>FIELD_LABELS[g]||g).join(', ')}</button>`:''}<button data-correct="${pair.id}">Correct a field</button><button data-detail="${pair.a.paper}">Inspect ${esc(pair.a.method)} ↗</button><button data-detail="${pair.b.paper}">Inspect ${esc(pair.b.method)} ↗</button></div></article>`}
async function compareView(p){const focus=[...selected].filter(id=>p.papers.some(x=>x.id===id));$('#view').innerHTML=`${proposalsPanel(p)}<div class="toolbar"><div><h3>Does the comparison actually hold?</h3><small>${focus.length>=2?`Comparing ${focus.length} focused papers. `:'Comparing every pair of results on the same metric and dataset. '}Missing context gives “insufficient evidence”, never “incompatible”.</small></div><div><button id="choose">Focus papers</button> ${focus.length>=2?'<button id="clear-focus">Show all</button>':''}</div></div><div id="matched"><div class="empty">Checking experimental context…</div></div>`;bindProposals(p);
  $('#choose').onclick=()=>{modal(`<h2>Focus on papers</h2>${p.papers.map(x=>`<label><input type="checkbox" data-select="${x.id}" ${selected.has(x.id)?'checked':''}> ${esc(x.title)}</label>`).join('')}<button class="primary" id="apply-selection">Compare selected papers</button>`);$('#apply-selection').onclick=()=>{selected=new Set([...document.querySelectorAll('[data-select]:checked')].map(x=>x.dataset.select));$('#dialog').close();compareView(p)}};if($('#clear-focus'))$('#clear-focus').onclick=()=>{selected.clear();compareView(p)};
  try{const key=p.id+':'+p.revision+':'+focus.join(',');const r=comparisonCache.key===key?comparisonCache.data:await api('research/compare',{id:p.id,papers:focus});comparisonCache={key,data:r};if(!$('#matched'))return;
    const s=r.summary;const show=r.pairs.filter(x=>(pairFilter==='all'||x.outcome===pairFilter)&&(!pairQuery||JSON.stringify([x.a.method,x.b.method,x.a.dataset,x.a.title,x.b.title]).toLowerCase().includes(pairQuery)));
    $('#matched').innerHTML=r.pairs.length?`<div class="outcome-summary">${['all','comparable','incompatible','insufficient'].map(k=>`<button class="outcome-filter f-${k} ${pairFilter===k?'active':''}" data-filter="${k}"><b>${k==='all'?r.pairs.length:s[k]}</b>${k==='all'?'All pairs':OUTCOME[k][0]}<small>${k==='all'?`${s.differentDataset} other-dataset and ${s.differentHorizon||0} other-horizon pairs not listed`:OUTCOME[k][1]}</small></button>`).join('')}</div><input type="search" id="pair-search" placeholder="Filter by model, dataset, or paper…" value="${esc(pairQuery)}" aria-label="Filter comparisons"><div class="pair-list">${show.slice(0,60).map(x=>pairCard(p,x)).join('')||'<div class="empty">No comparisons match this filter.</div>'}</div>${show.length>60?`<p class="hint">Showing 60 of ${show.length}. Narrow the filter to see more.</p>`:''}`:`<div class="empty">No pairs of results share a metric and dataset yet. ${r.rows} results extracted. Add papers or inspect the evidence.</div>`;
    document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{pairFilter=b.dataset.filter;compareView(p)});const search=$('#pair-search');if(search)search.oninput=()=>{pairQuery=search.value.toLowerCase();clearTimeout(search.t);search.t=setTimeout(()=>{compareView(p).then(()=>{const s=$('#pair-search');if(s){s.focus();s.setSelectionRange(s.value.length,s.value.length)}})},250)};
    document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.detail));
    document.querySelectorAll('[data-investigate-pair]').forEach(b=>b.onclick=()=>{const pair=r.pairs.find(x=>x.id===b.dataset.investigatePair);const fields=[...new Set(pair.checks.filter(c=>['missing','conflict','caveat'].includes(c.status)&&c.field!=='name').map(c=>c.field==='horizon'?['horizon','aggregation']:[c.field]).flat())];investigate(p,[{paper:pair.a.paper,metric:pair.a.metric,fields},{paper:pair.b.paper,metric:pair.b.metric,fields}],pair.id)});
    document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>correctDialog(p,r.pairs.find(x=>x.id===b.dataset.correct)))}catch(e){toast(e.message)}}
function correctDialog(p,pair){modal(`<div class="kicker">RESEARCHER CORRECTION</div><h2>Correct the experimental context.</h2><p>Your correction is recorded with your reason. Relay recomputes every affected comparison, marks dependent manuscript claims stale, and keeps the previous state as a checkpoint you can branch from.</p><label>Result<select id="fix-side"><option value="a">${esc(pair.a.method)} ${esc(pair.a.value)} · ${esc(pair.a.title.slice(0,60))}</option><option value="b">${esc(pair.b.method)} ${esc(pair.b.value)} · ${esc(pair.b.title.slice(0,60))}</option></select></label><label>Field<select id="fix-field">${['dataset','split','horizon','aggregation','metricDefinition','provenance','preprocessing','datasetVersion','method'].map(f=>`<option value="${f}">${FIELD_LABELS[f]}</option>`).join('')}</select></label><p id="fix-current" class="hint"></p><label>Correct value<input type="text" id="fix-value"></label><label>Why is this correct? <small>(table, appendix, code line, or author statement)</small><textarea id="fix-note" placeholder="The paper text says 70/20/10 but its data script uses 70/10/20."></textarea></label><button class="primary" id="fix-go">Apply correction</button>`);
  const show=()=>{const r=pair[$('#fix-side').value],f=$('#fix-field').value;$('#fix-current').textContent='Current value: '+r[f];$('#fix-value').value=known(r[f])?r[f]:''};$('#fix-side').onchange=show;$('#fix-field').onchange=show;show();
  $('#fix-go').onclick=async()=>{const r=pair[$('#fix-side').value];try{await api('research/update',{id:p.id,revision:p.revision,action:'correct',paper:r.paper,metric:r.metric,field:$('#fix-field').value,value:$('#fix-value').value,note:$('#fix-note').value});$('#dialog').close();await refresh(true);tab='corrections';routeTo();render();toast('Correction applied. Here is what it changed.')}catch(e){toast(e.message)}}}

function correctionsView(p){const list=p.corrections||[];$('#view').innerHTML=`${proposalsPanel(p)}<div class="toolbar"><div><h3>What changed when the evidence changed</h3><small>Each correction recomputes comparisons, marks dependent claims stale, and keeps the earlier state as a checkpoint.</small></div>${(p.draft&&['relatedWork','comparisons'].some(s=>(p.draft[s]||[]).some(i=>i.stale)))?`<button class="primary" id="regen" ${busy(p)?'disabled':''}>Regenerate stale claims</button>`:''}</div>${list.length?`<div class="correction-list">${list.map(c=>`<article class="correction status-${esc(c.status)}"><header><span class="badge">${esc({stale:'Claims need regeneration','affects-comparisons':'Comparisons changed','no-dependents':'No dependent results',regenerated:'Claims regenerated',reviewed:'Reviewed'}[c.status]||c.status)}</span><strong>${esc(c.result)}</strong><small>${esc(c.paperTitle.slice(0,80))} · ${esc(c.origin)} · ${esc(c.at.slice(0,16).replace('T',' '))}</small></header><div class="change-list">${c.changes.map(ch=>`<div><span>${esc(FIELD_LABELS[ch.field]||ch.field)}</span><span class="before">${esc(ch.before)}</span><span aria-hidden="true">→</span><span class="after">${esc(ch.after)}</span></div>`).join('')}</div>${c.note?`<p class="note">${esc(c.note)}</p>`:''}<h4>Comparisons affected <span class="badge">${c.comparisonChanges.length}</span></h4>${c.comparisonChanges.length?`<ul class="impact">${c.comparisonChanges.map(x=>`<li>${x.before===x.after?`<span class="o-${esc(x.after)}">Still ${esc((OUTCOME[x.after]?.[0]||x.after).toLowerCase())}</span> · reason updated`:`<span class="o-${esc(x.before)}">${esc(OUTCOME[x.before]?.[0]||x.before)}</span> → <span class="o-${esc(x.after)}">${esc(OUTCOME[x.after]?.[0]||x.after)}</span>`} <b>${esc(x.label)}</b><br><small>${esc((x.explanation||[]).join(' '))}</small></li>`).join('')}</ul>`:'<p class="hint">No comparison outcome changed.</p>'}<h4>Manuscript claims marked stale <span class="badge">${c.staleClaims.length}</span></h4>${c.staleClaims.length?`<ul class="impact">${c.staleClaims.map(s=>`<li><b>${esc(s.section==='comparisons'?'Evidence assessment':'Related work')}</b> “${esc(s.excerpt)}…”<br><small>${esc(s.reason)}</small></li>`).join('')}</ul>`:'<p class="hint">No drafted claim depended on this result.</p>'}<div class="actions"><button data-branch-before="${c.beforeNode}" data-label="${esc(c.result.slice(0,50))}">⑂ Open the state before this correction</button>${c.status!=='reviewed'?`<button data-resolve="${c.id}" ${busy(p)?'disabled':''}>Mark impact reviewed</button>`:''}</div></article>`).join('')}</div>`:'<div class="empty">No corrections yet. Accept an agent proposal or correct a field from the comparisons view; its consequences appear here.</div>'}`;
  bindProposals(p);if($('#regen'))$('#regen').onclick=async()=>{try{await api('research/regenerate',{id:p.id,revision:p.revision});toast('Regenerating the affected claims.');await refresh(true)}catch(e){toast(e.message)}};
  document.querySelectorAll('[data-branch-before]').forEach(b=>b.onclick=async()=>{try{const r=await api('research/branch',{id:p.id,node:b.dataset.branchBefore,next:'snapshot',name:'Before correction: '+b.dataset.label});await refresh(true);openProject(r.id,'compare');toast('Opened an independent branch with the earlier evidence.')}catch(e){toast(e.message)}});
  document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'resolve',correction:b.dataset.resolve});await refresh(true)}catch(e){toast(e.message)}})}

const CLAIM={supported:['Supported','Backed by a verified comparable comparison'],provisional:['Provisional','Comparable, but values are not yet verified'],attributed:['Attributed','Reports what a paper claims'],descriptive:['Descriptive','No performance claim'],unsupported:['Unsupported','Superiority claim without a comparable comparison']};
function paragraphHTML(i){const c=CLAIM[i.claim]||['',''];return `<div class="draft-paragraph ${i.stale?'stale':''}">${i.stale?`<div class="stale-flag">Stale: ${esc(i.staleReason)}</div>`:''}<p>${esc(i.text)} <small>[${esc((i.citations||[]).join(', '))}]</small> ${i.claim?`<span class="claim claim-${esc(i.claim)}" title="${esc(c[1])}">${esc(c[0])}</span>`:''}</p>${i.previous?`<details><summary>Previous text (before regeneration)</summary><p class="previous">${esc(i.previous)}</p></details>`:''}</div>`}
function writeView(p){const d=p.draft,staleN=d?['relatedWork','comparisons'].reduce((n,s)=>n+(d[s]||[]).filter(i=>i.stale).length,0):0,unsupported=d?['relatedWork','comparisons'].reduce((n,s)=>n+(d[s]||[]).filter(i=>i.claim==='unsupported').length,0):0;
  $('#view').innerHTML=`<div class="editor-tools"><button class="primary" id="draft" ${busy(p)?'disabled':''}>${p.tex?'Rewrite with feedback':'Generate reviewed draft'}</button>${staleN?`<button class="accent" id="regen-write" ${busy(p)?'disabled':''}>Regenerate ${staleN} stale claim${staleN>1?'s':''}</button>`:''}<button id="save-tex">Save edits</button><button id="compile" ${!p.tex?'disabled':''}>Compile PDF</button><a href="/api/research/export/${p.id}" download="relay-research.zip">Export Overleaf ZIP ↗</a><span class="review-count">${p.papers.filter(x=>x.reviewed).length} reviewed papers</span></div>${staleN?`<div class="notice warn">${staleN} paragraph${staleN>1?'s depend':' depends'} on evidence that changed. Regenerate after reviewing the corrections, or edit by hand.</div>`:''}${unsupported?`<div class="notice error">${unsupported} paragraph${unsupported>1?'s make':' makes'} a superiority claim without a comparable comparison. Edit or regenerate before approving.</div>`:''}<div class="notice">The manuscript proposes a study. It includes the comparison outcomes and the experimental controls they imply. No experiment for your question has been run.</div><div class="editor-layout"><div class="editor"><div class="editor-bar"><select id="editor-file" aria-label="Manuscript file" style="width:175px"><option value="tex" ${editorFile==='tex'?'selected':''}>main.tex</option><option value="bib" ${editorFile==='bib'?'selected':''}>references.bib</option></select><span id="save-state">Saved locally · revision ${p.revision}</span></div><textarea id="code" aria-label="LaTeX source" spellcheck="false">${esc(p[editorFile]||'')}</textarea></div><div class="editor"><div class="editor-bar"><span id="preview-label">${p.compile?.ok?'Last compiled PDF':'Claims and evidence'}</span><span>${p.compile?.ok?'<button id="show-claims">Show claims</button>':''} <label><input type="checkbox" id="draft-reviewed" ${p.draftReviewed?'checked':''}> Human reviewed</label></span></div><div id="preview">${p.compile?.ok&&!staleN?`<iframe title="Compiled manuscript PDF" src="/api/research/pdf/${p.id}/${p.compile.hash}"></iframe>`:claimsPreview(p)}</div></div></div><details><summary>Compilation log & export notes</summary><pre class="logs" id="compile-log">${esc(p.compile?.log||'No compilation yet.')}</pre><p>Import the ZIP as a new Overleaf project. It includes main.tex, references.bib, and the evidence record with every correction. This app does not edit an existing Overleaf account.</p></details>`;
  $('#code').oninput=()=>{dirty=true;$('#save-state').textContent='Unsaved edits';$('#draft-reviewed').checked=false};$('#draft-reviewed').onchange=()=>{dirty=true;$('#save-state').textContent='Unsaved review'};$('#editor-file').onchange=async()=>{const next=$('#editor-file').value;if(dirty)try{await saveEditor()}catch(e){toast(e.message);$('#editor-file').value=editorFile;return}editorFile=next;writeView(current())};$('#save-tex').onclick=async()=>{try{await saveEditor();toast('Manuscript saved.')}catch(e){toast(e.message)}};$('#draft').onclick=()=>draftDialog(p);if($('#show-claims'))$('#show-claims').onclick=()=>{$('#preview').innerHTML=claimsPreview(p);$('#preview-label').textContent='Claims and evidence'};
  if($('#regen-write'))$('#regen-write').onclick=async()=>{try{if(dirty)await saveEditor();const latest=current();await api('research/regenerate',{id:latest.id,revision:latest.revision});toast('Regenerating the affected claims.');await refresh(true)}catch(e){toast(e.message)}};
  $('#compile').onclick=async()=>{const b=$('#compile');b.disabled=true;b.textContent='Compiling…';try{await saveEditor();const latest=current();const r=await api('research/compile',{id:latest.id,revision:latest.revision});$('#compile-log').textContent=r.log;if(r.ok){$('#preview').innerHTML=`<iframe title="Compiled manuscript PDF" src="${esc(r.url)}"></iframe>`;$('#preview-label').textContent='Compiled PDF';toast('PDF compiled successfully.')}else toast('LaTeX compilation failed. Open the log for details.');await refresh()}catch(e){toast(e.message)}finally{if($('#compile')){$('#compile').disabled=false;$('#compile').textContent='Compile PDF'}}}}
function claimsPreview(p){const d=p.draft;if(!d)return '<div class="preview"><h3>Your next draft starts with evidence.</h3><p>Review papers in the Evidence step and include the ones you checked. The agent drafts related work, an evidence assessment built from the comparison outcomes, and the next defensible experiment.</p></div>';return `<div class="preview"><h3>Abstract ${d.summaryStale?'<span class="claim claim-unsupported">Review after corrections</span>':''}</h3><p>${esc(d.abstract)}</p><h3>Related work</h3>${(d.relatedWork||[]).map(paragraphHTML).join('')}<h3>Evidence assessment</h3>${(d.comparisons||[]).map(paragraphHTML).join('')||'<p>No comparison paragraphs.</p>'}${(d.pairTable||[]).length?`<table class="mini-table"><thead><tr><th>Result A</th><th>Result B</th><th>Outcome</th></tr></thead><tbody>${d.pairTable.map(r=>`<tr><td>${esc(r.a)}</td><td>${esc(r.b)}</td><td><span class="o-${esc(r.outcome)}">${esc(OUTCOME[r.outcome]?.[0]||r.outcome)}</span></td></tr>`).join('')}</tbody></table>`:''}<h3>Proposed study</h3><p class="prewrap">${esc(d.study)}</p>${(d.controls||[]).length?`<h3>Controls required by the evidence</h3><ul>${d.controls.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ul>`:''}</div>`}
async function saveEditor(){const p=current();const tex=editorFile==='tex'?$('#code').value:p.tex,bib=editorFile==='bib'?$('#code').value:p.bib;await api('research/update',{id:p.id,revision:p.revision,action:'save',tex,bib,reviewed:$('#draft-reviewed').checked});dirty=false;await refresh();}
function draftDialog(p){modal(`<div class="kicker">HUMAN IN THE LOOP</div><h2>Shape the argument before it is written.</h2><p>The agent will use ${p.papers.filter(x=>x.reviewed).length} reviewed papers and their comparison outcomes. It may only claim one method is better when the comparison holds; otherwise it must explain why the numbers cannot be compared.</p><label>Your direction, corrections, or exclusions<textarea id="feedback" placeholder="Focus on which baselines I can re-run under one protocol. Do not claim we have run experiments.">${esc(p.feedback||'')}</textarea></label><p>A new draft replaces the editor contents. The previous version stays in the execution record.</p><button class="primary" id="generate" ${!p.papers.some(x=>x.reviewed)?'disabled':''}>Generate proposed-study draft</button>`);$('#generate').onclick=async()=>{try{if(dirty)await saveEditor();const latest=current();await api('research/draft',{id:latest.id,revision:latest.revision,feedback:$('#feedback').value});$('#dialog').close();dirty=false;await refresh(true)}catch(e){toast(e.message)}}}

function executionView(p){executions.graph(p);const calls=p.calls||[];if(!calls.length)return;const ok=calls.filter(c=>c.ok).length,tokens=calls.reduce((n,c)=>n+c.totalTokens,0),ms=calls.reduce((n,c)=>n+(c.ms||0),0),retried=calls.filter(c=>c.attempts>1||c.repaired).length;
  $('#view').insertAdjacentHTML('beforeend',`<section class="side-card calls"><h3>Model calls <span class="badge">${calls.length}</span></h3><p>${ok} succeeded · ${calls.length-ok} failed · ${retried} recovered by retry or JSON repair · ${tokens.toLocaleString()} tokens · ${(ms/1000).toFixed(1)} s of model time. Every call records its model, latency, and token use.</p><div class="table-wrap"><table><thead><tr><th>Step</th><th>Model</th><th>Time</th><th>Tokens</th><th>Attempts</th><th>Result</th></tr></thead><tbody>${calls.slice(-40).reverse().map(c=>`<tr><td>${esc(c.kind)}</td><td>${esc(c.model)}</td><td>${((c.ms||0)/1000).toFixed(1)} s</td><td>${(c.totalTokens||0).toLocaleString()}</td><td>${c.attempts}${c.repaired?' · JSON repaired':''}${c.retries?' · '+esc(c.retries.join(', ')):''}</td><td>${c.ok?'OK':esc(c.error||'failed')}</td></tr>`).join('')}</tbody></table></div></section>`)}

$('#model-button').onclick=()=>{modal(`<div class="kicker">RESEARCH AGENT</div><h2>Choose your model.</h2><p>Models are fetched live from your configured provider. Existing investigations keep the model they started with.</p><label>Provider<select id="provider"><option value="nebius" ${provider==='nebius'?'selected':''}>Nebius Token Factory</option><option value="ollama" ${provider==='ollama'?'selected':''}>Ollama Cloud</option></select></label><label>Model<select id="models"><option>Loading live catalog…</option></select></label><p id="model-info"></p><button class="primary" id="use-model" disabled>Use selected model</button>`);let generation=0;async function load(){const n=++generation;$('#use-model').disabled=true;try{const r=await api('models?provider='+$('#provider').value);if(n!==generation||!$('#models'))return;const want=$('#provider').value===provider&&model?model:r.default;$('#models').innerHTML=r.models.map(m=>`<option ${m===want?'selected':''}>${esc(m)}</option>`).join('');$('#model-info').textContent=r.models.length+' available models · credentials stay on the local companion';$('#use-model').disabled=!r.models.length}catch(e){if($('#model-info'))$('#model-info').textContent=e.message}}$('#provider').onchange=load;load();$('#use-model').onclick=()=>{provider=$('#provider').value;model=$('#models').value;localStorage.setItem('relay-provider',provider);localStorage.setItem('relay-model',model);$('#dialog').close();sidebar();toast('Model selected for new investigations.')}};
const executions=executionUI({$,esc,api,modal,toast,getProjects:()=>projects,getLegacy:()=>legacyRuns,getCurrent:current,openProject,openTab,refresh});
if(initialRoute.get('node'))executions.setNode(initialRoute.get('node'));
try{const boot=await api('state');token=boot.token;legacyRuns=boot.runs;if(!provider){provider=boot.providers?.nebius?'nebius':'ollama';model=provider==='nebius'?boot.model:'gpt-oss:120b'}await refresh(true)}catch(e){toast(e.message)}setInterval(()=>refresh(),2200);
